    public Map<String, Object> handlePong(Client client, Map<String, Object> message)
    {
        //
        //   {
        //       "success": true,
        //       "ret_msg": "pong",
        //       "conn_id": "db3158a0-8960-44b9-a9de-ac350ee13158",
        //       "request": { op: "ping", args: null }
        //   }
        //
        //   { pong: 1653296711335 }
        //
        //
        //   {
        //       "req_id": "2",
        //       "op": "pong",
        //       "args": [ "1757405570352" ],
        //       "conn_id": "d266o6hqo29sqmnq4vk0-1yus1"
        //   }
        //
        client.lastPong = ((Number)this.safeInteger(message, "pong", this.milliseconds())).longValue();
        return message;
    }

    public Map<String, Object> handleAuthenticate(Client client, Map<String, Object> message)
    {
        //
        //    {
        //        "success": true,
        //        "ret_msg": '',
        //        "op": "auth",
        //        "conn_id": "ce3dpomvha7dha97tvp0-2xh"
        //    }
        //
        //    {
        //        "retCode":0,
        //        "retMsg":"OK",
        //        "op":"auth",
        //        "connId":"cojifin88smerbj9t560-404"
        //    }
        //
        //    {
        //        "success": true,
        //        "ret_msg": "",
        //        "op": "auth",
        //        "conn_id": "d266o6hqo29sqmnq4vk0-1yus1"
        //    }
        //
        Boolean success = (Boolean) this.safeBool(message, "success");
        Long code = this.safeInteger(message, "retCode");
        String messageHash = "authenticated";
        if ((java.util.Objects.equals(success, true)) || ((code != null && code == 0)))
        {
            io.github.ccxt.ws.Future future = (io.github.ccxt.ws.Future)this.safeValue(client.futures, messageHash);
            ((io.github.ccxt.ws.Future)future).resolve(true);
        } else
        {
            var error = new AuthenticationError(((this.id + " ") + this.json(message)));
            client.reject(error, messageHash);
            if (((Map<?, ?>)client.subscriptions).containsKey(messageHash))
            {
                ((Map<String,Object>)client.subscriptions).remove(messageHash);
            }
        }
        return message;
    }

